#!/usr/bin/env python3
"""Fail a commit when the index contains generated Goose C above a size limit.

The marker is the compiler's own header, not the file name:

    /* Generated by the Goose compiler from <source>. Do not edit.
    ...
    /* ==== runtime.h ==== */

Usage:
    python3 tools/check-generated-files.py            # index vs HEAD
    python3 tools/check-generated-files.py --all      # flag any generated C
    python3 tools/check-generated-files.py --mb 1     # size limit (default 1)

Intended as a pre-commit hook (see tools/README or the report). Hand-written C
is never matched, even when it is large. A generated file below the limit is
printed as a warning; a generated file at or above it fails the run.
"""

from __future__ import annotations

import argparse
import subprocess
import sys

MARKER_SOURCE = b"/* Generated by the Goose compiler from "
MARKER_DO_NOT_EDIT = b"Do not edit."
MARKER_RUNTIME = b"/* ==== runtime.h ==== */"


def git(*args: str, text: bool = True):
    return subprocess.run(["git", *args], stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, text=text, check=False)


def staged_files() -> list[str]:
    out = git("diff", "--cached", "--name-only", "--diff-filter=ACMR", "-z")
    if out.returncode != 0:
        print(f"check-generated-files: git diff failed: {out.stderr.strip()}", file=sys.stderr)
        raise SystemExit(2)
    return [p for p in out.stdout.split("\0") if p]


def index_size(path: str) -> int:
    out = git("cat-file", "-s", f":{path}")
    if out.returncode != 0:
        return -1
    try:
        return int(out.stdout.strip())
    except ValueError:
        return -1


def index_head(path: str, limit: int = 512) -> bytes:
    out = git("show", f":{path}", text=False)
    if out.returncode != 0:
        return b""
    return out.stdout[:limit]


def is_generated_goose_c(path: str, head: bytes) -> bool:
    if not path.endswith(".c"):
        return False
    return (head.startswith(MARKER_SOURCE)
            and MARKER_DO_NOT_EDIT in head
            and MARKER_RUNTIME in head)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--mb", type=float, default=1.0,
                    help="size limit in MiB (default 1)")
    ap.add_argument("--all", action="store_true",
                    help="fail on any generated C, regardless of size")
    args = ap.parse_args()

    limit = int(args.mb * 1024 * 1024)
    failed: list[tuple[str, int]] = []
    warned: list[tuple[str, int]] = []

    for path in staged_files():
        if not path.endswith(".c"):
            continue
        size = index_size(path)
        if size < 0:
            continue
        head = index_head(path)
        if not is_generated_goose_c(path, head):
            continue
        if args.all or size >= limit:
            failed.append((path, size))
        else:
            warned.append((path, size))

    for path, size in warned:
        print(f"warning: generated Goose C below the limit: {path} ({size} bytes)")

    if failed:
        print("error: generated Goose C is staged for commit:", file=sys.stderr)
        for path, size in failed:
            print(f"  {path} ({size / 1048576:.1f} MiB)", file=sys.stderr)
        print("regenerate it from the .goose source instead of committing it;\n"
              "if this experiment must keep it, raise --mb with a written reason.",
              file=sys.stderr)
        return 1

    print(f"check-generated-files: ok ({len(warned)} generated file(s) below limit)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
